      // Basic HTML escaping helpers to prevent HTML/JS injection when rendering
      escapeHTML(str2 = "") {
        return String(str2).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
      },
