      g.appendChild(svg("line", { x1: p.x, y1: p.y, x2: q.x, y2: q.y, class: "rpm-map-link" + (e.secret ? " rpm-map-secret" : "") + (e.type === "corridor" ? " rpm-map-corridor" : "") }));
      exitMarks(g, e, (p.x + q.x) / 2, (p.y + q.y) / 2);
